/**
 * ConversationListItem Component
 *
 * Single conversation item in the list
 * Phase 6: User Story 4 - Real-Time Message Reception
 */

import React from 'react';
import { ListGroup, Badge } from 'react-bootstrap';
import { formatDistanceToNow } from 'date-fns';

const ConversationListItem = ({ conversation, isActive, onClick }) => {
  const timestamp = conversation.last_message_at
    ? formatDistanceToNow(new Date(conversation.last_message_at), { addSuffix: true })
    : '';

  // Build display name with campaign/agent info to distinguish conversations
  const displayName = () => {
    const baseName = conversation.lead_name || conversation.phone_number;

    // If there's a campaign_id or assigned_user, show it to distinguish conversations
    const extraInfo = [];


    if (conversation.campaign_name) {
      // Show shortened campaign name
      const campaignName = conversation.campaign_name.length > 20
        ? conversation.campaign_name.substring(0, 17) + '...'
        : conversation.campaign_name;
      extraInfo.push(campaignName);
    }

    // Show assigned user if available (for admin view)
    if (conversation.assigned_user_id && conversation.assigned_user_name) {
      extraInfo.push(conversation.assigned_user_name);
    }

    return extraInfo.length > 0
      ? `${baseName} (${extraInfo.join(' - ')})`
      : baseName;
  };

  return (
    <ListGroup.Item
      action
      active={isActive}
      onClick={onClick}
      className="d-flex justify-content-between align-items-start"
    >
      <div className="flex-grow-1" style={{ minWidth: 0, overflow: 'hidden' }}>
        <div className="d-flex justify-content-between align-items-center mb-1">
          <strong style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', flex: 1 }}>
            {displayName()}
          </strong>
          <small className={`ms-2 ${isActive ? 'text-white-50' : 'text-muted'}`} style={{ flexShrink: 0 }}>
            {timestamp}
          </small>
        </div>
        <p className={`mb-0 small ${isActive ? 'text-white-50' : 'text-muted'}`} style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {conversation.last_message_direction === 'outgoing' && 'You: '}
          {conversation.last_message || 'No messages yet'}
        </p>
      </div>
      {conversation.unread_count > 0 && (
        <Badge bg="primary" pill className="ms-2" style={{ flexShrink: 0 }}>
          {conversation.unread_count}
        </Badge>
      )}
    </ListGroup.Item>
  );
};

export default ConversationListItem;

