/**
 * WhatsApp Text Formatter
 *
 * Parses WhatsApp text formatting and converts to React elements
 * Supports: *bold*, _italic_, ~strikethrough~, `monospace`
 */

import React from 'react';

/**
 * Formats WhatsApp-style text to React elements
 * @param {string} text - The text to format
 * @returns {React.ReactNode} - Formatted React elements
 */
export const formatWhatsAppText = (text) => {
  if (!text || typeof text !== 'string') {
    return text;
  }

  // Regular expressions for WhatsApp formatting
  // Using negative lookbehind/lookahead to avoid matching escaped characters
  const patterns = [
    { regex: /\*([^*]+)\*/g, tag: 'strong' },           // *bold*
    { regex: /_([^_]+)_/g, tag: 'em' },                 // _italic_
    { regex: /~([^~]+)~/g, tag: 's' },                  // ~strikethrough~
    { regex: /`([^`]+)`/g, tag: 'code' },               // `monospace`
  ];

  // Process the text by splitting and replacing
  let result = [];
  let remaining = text;
  let keyIndex = 0;

  // Combined regex to find all formatting markers
  const combinedRegex = /(\*[^*]+\*|_[^_]+_|~[^~]+~|`[^`]+`)/g;

  let lastIndex = 0;
  let match;

  while ((match = combinedRegex.exec(text)) !== null) {
    // Add text before the match
    if (match.index > lastIndex) {
      result.push(text.substring(lastIndex, match.index));
    }

    const matchedText = match[0];
    const innerText = matchedText.slice(1, -1);
    const marker = matchedText[0];

    // Determine the tag based on the marker
    let element;
    switch (marker) {
      case '*':
        element = <strong key={keyIndex++}>{formatWhatsAppText(innerText)}</strong>;
        break;
      case '_':
        element = <em key={keyIndex++}>{formatWhatsAppText(innerText)}</em>;
        break;
      case '~':
        element = <s key={keyIndex++}>{formatWhatsAppText(innerText)}</s>;
        break;
      case '`':
        element = <code key={keyIndex++} className="whatsapp-monospace">{innerText}</code>;
        break;
      default:
        element = matchedText;
    }

    result.push(element);
    lastIndex = match.index + matchedText.length;
  }

  // Add remaining text after the last match
  if (lastIndex < text.length) {
    result.push(text.substring(lastIndex));
  }

  // If no formatting was found, return the original text
  if (result.length === 0) {
    return text;
  }

  return result;
};

/**
 * Strips WhatsApp formatting markers from text (for plain text display)
 * @param {string} text - The text to strip
 * @returns {string} - Plain text without formatting markers
 */
export const stripWhatsAppFormatting = (text) => {
  if (!text || typeof text !== 'string') {
    return text;
  }

  return text
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/_([^_]+)_/g, '$1')
    .replace(/~([^~]+)~/g, '$1')
    .replace(/`([^`]+)`/g, '$1');
};

export default formatWhatsAppText;

