/**
 * MessageItem Component
 *
 * Displays a single message in the conversation
 * Phase 6: User Story 4 - Real-Time Message Reception
 */

import React, { useState } from 'react';
import { Card, Modal, OverlayTrigger, Tooltip } from 'react-bootstrap';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import DocumentViewer from './DocumentViewer';
import AudioPlayer from './AudioPlayer';
import VideoPlayer from './VideoPlayer';
import InteractiveMessage from './InteractiveMessage';
import './MessageItem.css';

const MessageItem = ({ message }) => {
  const isIncoming = message.direction === 'incoming';
  const timestamp = message.createdAt ? format(new Date(message.createdAt), 'HH:mm') : '';
  const [showImagePreview, setShowImagePreview] = useState(false);

  // Format detailed timestamp with status
  const getDetailedTimestamp = () => {
    const dateField = message.createdAt || message.created_at;
    if (!dateField) return '';

    const date = new Date(dateField);
    if (isNaN(date.getTime())) return '';

    const formattedDate = format(date, "dd/MM/yy 'a las' h:mm a", { locale: es });

    if (isIncoming) {
      return `Recibido el: ${formattedDate}`;
    } else {
      const statusText = {
        'sent': 'Enviado',
        'delivered': 'Entregado',
        'read': 'Leído',
        'failed': 'Fallido'
      }[message.status] || 'Enviado';

      return `Enviado el: ${formattedDate} - ${statusText}`;
    }
  };

  // Tooltip with detailed timestamp
  const renderTooltip = (props) => (
    <Tooltip id="message-timestamp-tooltip" {...props}>
      {getDetailedTimestamp()}
    </Tooltip>
  );

  return (
    <>
    <div className={`d-flex mb-3 ${isIncoming ? 'justify-content-start' : 'justify-content-end'}`}>
      <div style={{ maxWidth: '70%', display: 'flex', flexDirection: 'column' }}>
        <Card
          className={`message-card ${isIncoming ? 'bg-light' : 'bg-primary text-white'}`}
        >
          <Card.Body className="py-2 px-3">
          {/* Sender name for outgoing messages */}
          {!isIncoming && message.sender && (
            <div className="small text-white-50 mb-1">
              {message.sender.name}
            </div>
          )}

          {/* Message content */}
          <div className="message-content">
            {/* Image */}
            {message.message_type === 'image' && message.file_url && (
              <img
                src={message.file_url.startsWith('http') ? message.file_url : `${import.meta.env.VITE_API_URL}${message.file_url}`}
                alt="attachment"
                className="img-fluid rounded mb-2 message-image"
                style={{
                  maxWidth: '100%',
                  width: 'auto',
                  maxHeight: '250px',
                  objectFit: 'contain',
                  cursor: 'pointer',
                  display: 'block'
                }}
                onClick={() => setShowImagePreview(true)}
                title="Click para ampliar"
              />
            )}

            {/* Document */}
            {message.message_type === 'document' && message.file_url && (
              <DocumentViewer
                fileUrl={message.file_url}
                fileName={message.message_content.replace('[Documento: ', '').replace(']', '')}
                isIncoming={isIncoming}
              />
            )}

            {/* Audio */}
            {message.message_type === 'audio' && message.file_url && (
              <AudioPlayer
                fileUrl={message.file_url}
                isIncoming={isIncoming}
              />
            )}

            {/* Video */}
            {message.message_type === 'video' && message.file_url && (
              <VideoPlayer
                fileUrl={message.file_url}
                caption={message.message_content !== '[Video]' ? message.message_content : null}
                isIncoming={isIncoming}
              />
            )}

            {/* Interactive Messages (buttons and lists) */}
            {(message.message_type === 'interactive' ||
              message.message_type === 'button_reply' ||
              message.message_type === 'list_reply' ||
              (message.message_type === 'template' && message.interactive_type)) && (
              <InteractiveMessage message={message} isIncoming={isIncoming} />
            )}

            {/* Text content (only show if not a media-only message and not fully interactive) */}
            {(message.message_type === 'text' ||
              (message.message_type === 'template' && !message.interactive_type) ||
              (message.message_type === 'image' && message.message_content && message.message_content !== '[Image]')) && (
              <div className="message-text">{message.message_content}</div>
            )}
          </div>

          {/* Timestamp and status */}
          <div className={`d-flex align-items-center justify-content-end mt-1 gap-2 small ${isIncoming ? 'text-muted' : 'text-white-50'}`}>
            {!isIncoming && (
              <span>
                {message.status === 'sent' && '✓'}
                {message.status === 'delivered' && '✓✓'}
                {message.status === 'read' && <span className="text-info">✓✓</span>}
                {message.status === 'failed' && '✗'}
              </span>
            )}
          </div>
        </Card.Body>
      </Card>

      {/* Detailed timestamp below message */}
      <div className={`message-timestamp-detail ${isIncoming ? 'text-start' : 'text-end'}`}>
        <small className="text-muted">
          {getDetailedTimestamp()}
        </small>
      </div>
      </div>
    </div>

    {/* Image Preview Modal */}
    {message.message_type === 'image' && message.file_url && (
      <Modal
        show={showImagePreview}
        onHide={() => setShowImagePreview(false)}
        size="lg"
        scrollable
        className="image-preview-modal"
      >
        <Modal.Header closeButton style={{ border: 'none', paddingBottom: 0 }}>
          <Modal.Title>Vista previa</Modal.Title>
        </Modal.Header>
        <Modal.Body className="text-center" style={{ padding: '20px' }}>
          <img
            src={message.file_url.startsWith('http') ? message.file_url : `${import.meta.env.VITE_API_URL}${message.file_url}`}
            alt="Preview"
            style={{
              maxWidth: '100%',
              maxHeight: '70vh',
              objectFit: 'contain'
            }}
          />
          {message.message_content && message.message_content !== '[Image]' && (
            <p className="mt-3 text-muted">{message.message_content}</p>
          )}
        </Modal.Body>
        <Modal.Footer style={{ border: 'none', justifyContent: 'center' }}>
          <a
            href={message.file_url.startsWith('http') ? message.file_url : `${import.meta.env.VITE_API_URL}${message.file_url}`}
            download
            className="btn btn-primary"
            target="_blank"
            rel="noopener noreferrer"
          >
            Descargar imagen
          </a>
        </Modal.Footer>
      </Modal>
    )}
    </>
  );
};

export default MessageItem;

