      </div>
      </div>
    </div>

    {/* Image Preview Modal */}
    {message.message_type === 'image' && message.file_url && (
      <Modal
        show={showImagePreview}
        onHide={() => setShowImagePreview(false)}
        size="lg"
        scrollable
        className="image-preview-modal"
      >
        <Modal.Header closeButton style={{ border: 'none', paddingBottom: 0 }}>
          <Modal.Title>Vista previa</Modal.Title>
        </Modal.Header>
        <Modal.Body className="text-center" style={{ padding: '20px' }}>
          <img
            src={message.file_url.startsWith('http') ? message.file_url : `${import.meta.env.VITE_API_URL}${message.file_url}`}
            alt="Preview"
            style={{
              maxWidth: '100%',
              maxHeight: '70vh',
              objectFit: 'contain'
            }}
          />
          {message.message_content && message.message_content !== '[Image]' && (
            <p className="mt-3 text-muted">{message.message_content}</p>
          )}
        </Modal.Body>
        <Modal.Footer style={{ border: 'none', justifyContent: 'center' }}>
          <a
            href={message.file_url.startsWith('http') ? message.file_url : `${import.meta.env.VITE_API_URL}${message.file_url}`}
            download
            className="btn btn-primary"
            target="_blank"
            rel="noopener noreferrer"
          >
            Descargar imagen
          </a>
        </Modal.Footer>
      </Modal>
    )}
    </>
  );
};

export default MessageItem;

