/**
 * MessageItem Component Styles
 */

.message-card {
  border-radius: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  position: relative;
}

.message-content {
  word-wrap: break-word;
  word-break: break-word;
  max-width: 100%;
  overflow: hidden;
}

/* Image styles */
.message-image {
  max-width: 100%;
  height: auto;
  object-fit: contain;
}

/* Ensure images don't overflow in small containers */
@media (max-width: 576px) {
  .message-image {
    max-height: 200px;
  }
}

.message-text {
  white-space: pre-wrap;
  font-size: 14px;
  line-height: 1.4;
}

/* Tooltip styles */
#message-timestamp-tooltip {
  font-size: 12px;
  padding: 8px 12px;
  max-width: 300px;
}

#message-timestamp-tooltip .tooltip-inner {
  background-color: rgba(0, 0, 0, 0.9);
  padding: 8px 12px;
  border-radius: 6px;
  font-weight: 500;
}

/* Message status icons */
.message-card .text-info {
  color: #0d6efd !important;
}

/* Timestamp detail below message */
.message-timestamp-detail {
  margin-top: 4px;
  padding: 0 4px;
  font-size: 11px;
  line-height: 1.3;
  opacity: 0.8;
}

.message-timestamp-detail small {
  font-family: 'Lato', sans-serif;
  font-size: 11px;
  color: #666;
}

/* Image preview modal */
.image-preview-modal .modal-content {
  border-radius: 12px;
  overflow: hidden;
}

.image-preview-modal .modal-header {
  background-color: #f8f9fa;
}

.image-preview-modal .modal-body {
  background-color: #000;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

