    11→
    12→const InteractiveMessage = ({ message, isIncoming }) => {
    13→  const { interactive_type, interactive_data, message_content } = message;
    14→
    15→  // Early return if no interactive_type
    16→  if (!interactive_type) {
    17→    return (
    18→      <div className="interactive-message">
