/**
 * InteractiveMessage Component
 *
 * Displays interactive messages (buttons and lists) and their responses
 * Handles both outgoing interactive messages and incoming responses
 */

import React from 'react';
import { Card, Button, ListGroup } from 'react-bootstrap';
import PropTypes from 'prop-types';

const InteractiveMessage = ({ message, isIncoming }) => {
  const { interactive_type, interactive_data, message_content } = message;

  // Early return if no interactive_type
  if (!interactive_type) {
    return (
      <div className="interactive-message">
        <span className="badge bg-info mb-2">Mensaje interactivo</span>
        <div>{message_content}</div>
      </div>
    );
  }

  // Handle button reply (incoming response)
  if (interactive_type === 'button_reply') {
    return (
      <div className="interactive-response">
        <div className="d-flex align-items-center gap-2">
          <span className="badge bg-secondary">
            Respuesta de botón
          </span>
        </div>
        <div className="mt-2">
          <strong>{interactive_data?.title || message_content}</strong>
        </div>
        {interactive_data?.id && (
          <div className="small text-muted mt-1">
            ID: {interactive_data.id}
          </div>
        )}
      </div>
    );
  }

  // Handle list reply (incoming response)
  if (interactive_type === 'list_reply') {
    return (
      <div className="interactive-response">
        <div className="d-flex align-items-center gap-2">
          <span className="badge bg-secondary">
            Selección de lista
          </span>
        </div>
        <div className="mt-2">
          <strong>{interactive_data?.title || message_content}</strong>
        </div>
        {interactive_data?.description && (
          <div className="small mt-1">
            {interactive_data.description}
          </div>
        )}
        {interactive_data?.id && (
          <div className="small text-muted mt-1">
            ID: {interactive_data.id}
          </div>
        )}
      </div>
    );
  }

  // Handle outgoing button message
  if (interactive_type === 'button') {
    // If no interactive_data, show fallback with message content
    if (!interactive_data) {
      return (
        <div className="interactive-buttons">
          <div className="mb-2">{message_content}</div>
          <div className="small text-muted">
            <span className="badge bg-info">Botones interactivos</span>
          </div>
        </div>
      );
    }

    return (
      <div className="interactive-buttons">
        {/* Header/Body text */}
        {interactive_data.header && (
          <div className="fw-bold mb-2">
            {interactive_data.header}
          </div>
        )}
        {interactive_data.body && (
          <div className="mb-3">
            {interactive_data.body}
          </div>
        )}
        {interactive_data.footer && (
          <div className="small text-muted mb-2">
            {interactive_data.footer}
          </div>
        )}

        {/* Buttons */}
        {interactive_data.buttons && Array.isArray(interactive_data.buttons) && interactive_data.buttons.length > 0 && (
          <div className="d-flex flex-column gap-2">
            {interactive_data.buttons.map((button, index) => {
              // Check if button is a URL button
              const isUrlButton = button.type === 'url' || button.type === 'URL';
              const buttonUrl = button.url;

              if (isUrlButton && buttonUrl) {
                // Render as link for URL buttons
                return (
                  <a
                    key={index}
                    href={buttonUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className={`btn btn-outline-${isIncoming ? 'dark' : 'light'} btn-sm text-start d-flex align-items-center justify-content-between`}
                    style={{
                      textDecoration: 'none'
                    }}
                  >
                    <span>{button.text || button.title}</span>
                    <i className="bi bi-box-arrow-up-right ms-2"></i>
                  </a>
                );
              }

              // Render as disabled button for quick reply buttons
              return (
                <Button
                  key={index}
                  variant="outline-light"
                  size="sm"
                  disabled
                  className={`text-start ${isIncoming ? 'text-dark border-dark' : 'text-white border-white'}`}
                  style={{
                    cursor: 'default',
                    opacity: 0.8
                  }}
                >
                  {button.text || button.title}
                </Button>
              );
            })}
          </div>
        )}
      </div>
    );
  }

  // Handle outgoing list message
  if (interactive_type === 'list') {
    // If no interactive_data, show fallback with message content
    if (!interactive_data) {
      return (
        <div className="interactive-list">
          <div className="mb-2">{message_content}</div>
          <div className="small text-muted">
            <span className="badge bg-info">Lista interactiva</span>
          </div>
        </div>
      );
    }

    return (
      <div className="interactive-list">
        {/* Header/Body text */}
        {interactive_data.header && (
          <div className="fw-bold mb-2">
            {interactive_data.header}
          </div>
        )}
        {interactive_data.body && (
          <div className="mb-3">
            {interactive_data.body}
          </div>
        )}
        {interactive_data.footer && (
          <div className="small text-muted mb-2">
            {interactive_data.footer}
          </div>
        )}

        {/* Button text */}
        {interactive_data.button && (
          <Button
            variant="outline-light"
            size="sm"
            disabled
            className={`w-100 mb-2 ${isIncoming ? 'text-dark border-dark' : 'text-white border-white'}`}
            style={{
              cursor: 'default',
              opacity: 0.8
            }}
          >
            {interactive_data.button}
          </Button>
        )}

        {/* Sections with items */}
        {interactive_data.sections && Array.isArray(interactive_data.sections) && interactive_data.sections.length > 0 && (
          <div className="mt-2">
            {interactive_data.sections.map((section, sectionIndex) => (
              <div key={sectionIndex} className="mb-2">
                {section.title && (
                  <div className="small fw-bold mb-1" style={{
                    color: isIncoming ? '#666' : 'rgba(255,255,255,0.8)'
                  }}>
                    {section.title}
                  </div>
                )}
                <ListGroup variant="flush" className="small">
                  {section.rows && Array.isArray(section.rows) && section.rows.map((row, rowIndex) => (
                    <ListGroup.Item
                      key={rowIndex}
                      className={`border-0 ${isIncoming ? 'bg-light' : 'bg-primary'} px-2 py-1`}
                      style={{
                        color: isIncoming ? '#333' : 'rgba(255,255,255,0.9)',
                        fontSize: '0.85rem'
                      }}
                    >
                      <div className="fw-bold">{row.title}</div>
                      {row.description && (
                        <div className="small" style={{
                          color: isIncoming ? '#666' : 'rgba(255,255,255,0.7)'
                        }}>
                          {row.description}
                        </div>
                      )}
                    </ListGroup.Item>
                  ))}
                </ListGroup>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // Fallback for unknown interactive types
  return (
    <div className="interactive-message">
      <span className="badge bg-info mb-2">Mensaje interactivo</span>
      <div>{message_content}</div>
    </div>
  );
};

InteractiveMessage.propTypes = {
  message: PropTypes.shape({
    interactive_type: PropTypes.string,
    interactive_data: PropTypes.object,
    message_content: PropTypes.string,
  }).isRequired,
  isIncoming: PropTypes.bool.isRequired,
};

export default InteractiveMessage;

