     2→ * WhatsApp Text Formatter
     3→ *
     4→ * Parses WhatsApp text formatting and converts to React elements
     5→ * Supports: *bold*, _italic_, ~strikethrough~, `monospace`
     6→ */
     7→
     8→import React from 'react';
     9→
    10→/**
    11→ * Formats WhatsApp-style text to React elements
    12→ * @param {string} text - The text to format
    13→ * @returns {React.ReactNode} - Formatted React elements
    14→ */
    15→export const formatWhatsAppText = (text) => {
    16→  if (!text || typeof text !== 'string') {
    17→    return text;
    18→  }
    19→
    20→  // Regular expressions for WhatsApp formatting
    21→  // Using negative lookbehind/lookahead to avoid matching escaped characters
    22→  const patterns = [
    23→    { regex: /\*([^*]+)\*/g, tag: 'strong' },           // *bold*
    24→    { regex: /_([^_]+)_/g, tag: 'em' },                 // _italic_
    25→    { regex: /~([^~]+)~/g, tag: 's' },                  // ~strikethrough~
    26→    { regex: /`([^`]+)`/g, tag: 'code' },               // `monospace`
    27→  ];
    28→
    29→  // Process the text by splitting and replacing
    30→  let result = [];
    31→  let remaining = text;
    32→  let keyIndex = 0;
    33→
    34→  // Combined regex to find all formatting markers
    35→  const combinedRegex = /(\*[^*]+\*|_[^_]+_|~[^~]+~|`[^`]+`)/g;
    36→
    37→  let lastIndex = 0;
    38→  let match;
    39→
    40→  while ((match = combinedRegex.exec(text)) !== null) {
    41→    // Add text before the match
    42→    if (match.index > lastIndex) {
    43→      result.push(text.substring(lastIndex, match.index));
    44→    }
    45→
    46→    const matchedText = match[0];
    47→    const innerText = matchedText.slice(1, -1);
    48→    const marker = matchedText[0];
    49→
    50→    // Determine the tag based on the marker
    51→    let element;
    52→    switch (marker) {
    53→      case '*':
    54→        element = <strong key={keyIndex++}>{formatWhatsAppText(innerText)}</strong>;
    55→        break;
    56→      case '_':
    57→        element = <em key={keyIndex++}>{formatWhatsAppText(innerText)}</em>;
    58→        break;
    59→      case '~':
    60→        element = <s key={keyIndex++}>{formatWhatsAppText(innerText)}</s>;
    61→        break;
    62→      case '`':
    63→        element = <code key={keyIndex++} className="whatsapp-monospace">{innerText}</code>;
    64→        break;
    65→      default:
    66→        element = matchedText;
    67→    }
    68→
    69→    result.push(element);
    70→    lastIndex = match.index + matchedText.length;
    71→  }
    72→
    73→  // Add remaining text after the last match
    74→  if (lastIndex < text.length) {
    75→    result.push(text.substring(lastIndex));
    76→  }
    77→
    78→  // If no formatting was found, return the original text
    79→  if (result.length === 0) {
    80→    return text;
    81→  }
    82→
    83→  return result;
    84→};
    85→
    86→/**
    87→ * Strips WhatsApp formatting markers from text (for plain text display)
    88→ * @param {string} text - The text to strip
    89→ * @returns {string} - Plain text without formatting markers
    90→ */
    91→export const stripWhatsAppFormatting = (text) => {
    92→  if (!text || typeof text !== 'string') {
    93→    return text;
    94→  }
